"""Inputs for the `fn/ApplyCharacterControllerMove` unit (no-shape path).

The state block is pinned at the shared handle-table global
(`0x1442a0bc0`) and holds four table entries, three records and four live
entries. Record A has `+0x15c = 0`; record B has `+0x15c = 1`; the table's
space 2 decodes to a null record and space 3 to a count-0 record.

The velocity is a per-case pointee. Cases cover a changed velocity, an
unchanged xyz velocity (the early return), an inf/nan exponent in xyz (the
client declines) and in w only (ignored), a null/zero-path handle, the
record gate, count/entry/generation failures and the space bound.
"""

from __future__ import annotations

import struct
from math import inf, nan
from typing import List

from emu_oracle import ArgSpec

STATE_BASE = 0x00007ff7c8fc0bc0
STATE_LEN = 0x1000
STATE_HEX = ""
CASES = [(30064771072, [1.0, 2.0, 3.0, 4.0]), (30064771073, [5.0, 6.0, 7.0, 8.0]), (30064771074, [1.0, 2.0, 3.0, 9.0]), (30064771074, [1.0, 2.0, 3.0, 4.0]), (30064771073, [5.0, 6.0, 7.0, 8.0]), (30064771073, [5.0, 6.0, 7.0, inf]), (30064771072, [inf, 0.0, 0.0, 0.0]), (30064771072, [0.0, nan, 0.0, 0.0]), (30064771072, [0.0, 0.0, inf, 0.0]), (30064771072, [0.0, 0.0, 0.0, inf]), (281505041481728, [1.0, 2.0, 3.0, 4.0]), (562980018192384, [1.0, 2.0, 3.0, 4.0]), (844454994903040, [1.0, 2.0, 3.0, 4.0]), (30064771076, [1.0, 2.0, 3.0, 4.0]), (4611404573515448320, [1.0, 2.0, 3.0, 4.0]), (34359738367, [1.0, 2.0, 3.0, 4.0]), (34359738369, [1.0, 2.0, 3.0, 4.0]), (32212254720, [1.0, 2.0, 3.0, 4.0]), (30064771075, [1.0, 2.0, 3.0, 4.0])]


def _fbits(value: float) -> int:
    return struct.unpack("<I", struct.pack("<f", value))[0]


def make_args(i: int) -> List[ArgSpec]:
    handle, velocity = CASES[i % len(CASES)]
    return [
        ArgSpec(kind="u64", bits=handle),
        ArgSpec(
            kind="ptr",
            mem=b"".join(struct.pack("<I", _fbits(v)) for v in velocity),
            arena_offset=0x7000,
        ),
        ArgSpec(kind="u64", bits=STATE_BASE),
    ]
